static int spi_nor_capabilities_show ( struct seq_file * s , void * data ) { struct spi_nor * nor = s -> private ; struct spi_nor_flash_parameter * params = nor -> params ; u32 hwcaps = params -> hwcaps . mask ; int i , cmd ; seq_puts ( s , "Supported read modes by the flash\n" ) ; for ( i = 0 ; i < sizeof ( hwcaps ) * BITS_PER_BYTE ; i ++ ) { if ( ! ( hwcaps & BIT ( i ) ) ) { continue ; } cmd = spi_nor_hwcaps_read2cmd ( BIT ( i ) ) ; if ( cmd < 0 ) { continue ; } hwcaps &= ~ BIT ( i ) ; } seq_puts ( s , "\nSupported page program modes by the flash\n" ) ; for ( i = 0 ; i < sizeof ( hwcaps ) * BITS_PER_BYTE ; i ++ ) { if ( ! ( hwcaps & BIT ( i ) ) ) { continue ; } cmd = spi_nor_hwcaps_pp2cmd ( BIT ( i ) ) ; if ( cmd < 0 ) { continue ; } spi_nor_print_pp_cmd ( s , & params -> page_programs [ cmd ] ) ; hwcaps &= ~ BIT ( i ) ; } if ( hwcaps ) { seq_printf ( s , "\nunknown hwcaps 0x%x\n" , hwcaps ) ; } return 0 ; } 